const IG='https://www.instagram.com/vamknam.by/';
const products=[
{id:'savings',name:'Копилка «На мечту»',category:'Копилки',price:15,from:true,image:'savings.jpg',original:'7bad32496d2069e0.jpg',tag:'С вашим именем',desc:'Маленький шаг к большой мечте. Деревянная копилка с прозрачным окошком и именным оформлением — для первых накоплений и особенных планов.',size:'12 × 12 или 15 × 15 см',material:'Дерево, прозрачная вставка',note:'12 × 12 см — 15 BYN; 15 × 15 см — 20 BYN. От 5 штук: 10 и 15 BYN соответственно.',source:'https://www.instagram.com/vamknam.by/reel/DXla8o8oqEN/'},
{id:'house',name:'Мини-бар «Домик»',category:'Мини-бары',price:55,image:'house.jpg',original:'043578f271a851df.jpg',tag:'Именная гравировка',desc:'Подарок с характером и маленькой историей. У деревянного домика открывается крыша, а на фасаде можно разместить надпись по вашему желанию.',size:'Уточняется при заказе',material:'Дерево',note:'Наполнение на оригинальной фотографии показано для наглядности. Состав и комплектация согласовываются с мастером.',source:'https://www.instagram.com/vamknam.by/reel/DLE-qRQij8n/'},
{id:'tree',name:'Дерево благодарности',category:'Декор',price:105,image:'tree.jpg',original:'a6fadaf877678293.jpg',tag:'Особенный подарок',desc:'Тёплые слова, которые останутся рядом. Дети опускают в дерево листочки или сердечки со своими именами и благодарят любимого педагога. Можно добавить свою надпись.',size:'32 см',material:'Дерево, прозрачная вставка',note:'Можно выбрать оформление с листочками или сердечками. Текст и имена согласовываются перед изготовлением.',source:'https://www.instagram.com/vamknam.by/reel/DYB0228Ahm6/'},
{id:'cannon',name:'Мини-бар «Пушка»',category:'Мини-бары',price:65,image:'cannon.jpg',original:'aceaea69836cb9f5.jpg',tag:'Подарок с характером',desc:'Необычная деревянная подставка для подарка, который запомнят. Мастерская может добавить именную надпись — для близкого человека, коллеги или друга.',size:'Уточняется при заказе',material:'Дерево',note:'Бутылка и бокалы на оригинальной фотографии показаны для наглядности. Комплектацию уточните у мастера.',source:'https://www.instagram.com/vamknam.by/reel/DTzUWFhiBZA/'},
{id:'pen',name:'Именная ручка с подставкой',category:'Канцелярия',price:20,image:'00d05f14fb07a27b.jpg',original:'00d05f14fb07a27b.jpg',tag:'Символ 2027 года',originalOnly:true,desc:'Небольшой именной подарок с подставкой в виде символа года. Можно выбрать другой цвет и добавить имя.',size:'Подставка 11–12 × 9,5 см',material:'Материал уточняется у мастера',note:'1 штука — 20 BYN. От 5 штук — 15 BYN за штуку.',source:'https://www.instagram.com/vamknam.by/reel/DfO1_ZQgtpN/'}
];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cart;try{cart=JSON.parse(localStorage.getItem('vamknam-cart-v1')||'[]');if(!Array.isArray(cart))cart=[];cart=cart.filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99).map(x=>({...x,variant:x.variant==='large'?'large':'small',text:String(x.text||'').slice(0,140)}))}catch{cart=[]}
let activeCategory=new URLSearchParams(location.search).get('category')||'Все изделия';
const app=document.getElementById('app');
const icon=(n,c='')=>`<img class="${c}" src="assets/${n}.svg" alt="" loading="lazy">`;
const priceText=p=>`${p.from?'от ':''}${p.price} <small>BYN</small>`;
const money=n=>new Intl.NumberFormat('ru-BY').format(n);
function unitPrice(item){const p=products.find(p=>p.id===item.id);if(p.id==='savings')return item.variant==='large'?(item.qty>=5?15:20):(item.qty>=5?10:15);if(p.id==='pen'&&item.qty>=5)return 15;return p.price}
function saveCart(){localStorage.setItem('vamknam-cart-v1',JSON.stringify(cart));document.getElementById('cart-count').textContent=cart.reduce((n,x)=>n+x.qty,0)}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function addCart(id,text='',variant='small',qty=1){const found=cart.find(x=>x.id===id&&x.text===text&&x.variant===variant);if(found)found.qty=Math.min(99,found.qty+qty);else cart.push({id,text,variant,qty});saveCart();toast('Изделие добавлено в корзину')}
function card(p){return `<article class="product-card"><div class="product-picture"><a href="product/${p.id}/"><img src="assets/${p.image}" alt="${p.name}" loading="lazy" width="600" height="500"></a>${p.tag?`<span class="tag">${p.tag}</span>`:''}<button class="quick-add" data-add="${p.id}" aria-label="Добавить ${p.name} в корзину">+</button></div><p class="product-type">${p.category}</p><h3><a href="product/${p.id}/">${p.name}</a></h3><div class="product-meta"><span class="price">${priceText(p)}</span><a class="detail-link" href="product/${p.id}/">Подробнее ↗</a></div></article>`}
function breadcrumb(label,extra=''){return `<div class="breadcrumb"><a href="">Главная</a> &nbsp; / &nbsp; ${extra}${label}</div>`}
function home(){app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">Авторские изделия из дерева</div><h1>Создаём то,<br>что не купишь<br><em>в магазине.</em></h1><p>Именные подарки и декор, в которых живёт тепло.<br>Для вашего дома. Для ваших любимых.</p><a class="button" href="catalog/">Выбрать свой подарок <span>↗</span></a><div class="hero-bottom">${icon('leaf')}<span>Натуральное дерево. Ваши слова. Наша забота.</span></div></div><div class="hero-visual"><img src="assets/tree.jpg" alt="Дерево благодарности из дерева с именными сердечками" fetchpriority="high" width="900" height="750"><div class="hero-seal">СДЕЛАНО<em>с душой</em>ДЛЯ ВАС</div><a class="hero-label" href="product/tree/"><small>МАЛЕНЬКИЕ ВЕЩИ. БОЛЬШИЕ ЧУВСТВА.</small>Дерево благодарности <span>↗</span></a></div></section><div class="container"><div class="benefits"><div class="benefit">${icon('leaf')}<div><strong>Тепло натурального дерева</strong><small>Природа в каждой детали</small></div></div><div class="benefit">${icon('engrave')}<div><strong>Именно ваш подарок</strong><small>Имя, надпись или особая дата</small></div></div><div class="benefit">${icon('parcel')}<div><strong>По всей Беларуси</strong><small>Белпочта и Европочта</small></div></div></div><section class="section"><div class="section-head"><div><div class="eyebrow">Подарки со смыслом</div><h2>Созданы, чтобы радовать</h2></div><a class="text-link" href="catalog/">Весь каталог <span>↗</span></a></div><div class="products">${products.slice(0,4).map(card).join('')}</div><p class="visual-note">Студийные визуализации изделий. Оригинальные фотографии и публикации доступны на странице каждого товара.</p></section></div><section class="categories"><div class="container"><div class="section-head"><div><div class="eyebrow">Для дома и в подарок</div><h2>Найдите что-то своё</h2></div></div><div class="category-grid">${[['Копилки','pig','Для больших и маленьких мечтаний'],['Мини-бары','house','Подарки с характером'],['Декор','tree-icon','Детали, которые создают уют'],['Канцелярия','notebook','Для вдохновения каждый день']].map(([name,i,t])=>`<a class="category" href="catalog/?category=${encodeURIComponent(name)}">${icon(i)}<div><h3>${name}</h3><span>${t}</span></div><b>↗</b></a>`).join('')}</div></div></section><div class="container"><section class="custom"><div class="custom-visual"><img src="assets/house.jpg" alt="Авторский деревянный мини-бар в форме домика" loading="lazy" width="750" height="600"><div class="custom-caption">Ваши слова делают подарок особенным.</div></div><div><div class="eyebrow">Не просто вещь. Ваша история.</div><h2>Самые тёплые<br>подарки — <em>личные.</em></h2><p>Имя любимого человека, семейная дата или слова благодарности. Добавим то, что превратит красивую вещь в дорогую сердцу.</p><p>Есть собственная идея? Расскажите нам о ней — обсудим, как воплотить её в дереве.</p><a class="text-link" href="how-to-order/?custom=1">Обсудить свою идею <span>↗</span></a></div></section><section class="steps"><h2>От идеи до тёплых объятий</h2><div class="step-grid"><div class="step"><span class="step-num">01</span><h3>Выберите своё</h3><p>Найдите подарок в каталоге или расскажите нам о своей задумке.</p></div><div class="step"><span class="step-num">02</span><h3>Добавьте личное</h3><p>Обсудим надпись, оформление, стоимость и дату готовности.</p></div><div class="step"><span class="step-num">03</span><h3>Дарите с любовью</h3><p>Создадим ваш подарок и отправим в любую точку Беларуси.</p></div></div></section></div><section class="about" id="about"><div class="container about-inner"><div><div class="eyebrow">Знакомьтесь, это мы</div><h2>Ольга и Геннадий.<br>Дерево, идеи и немного души.</h2></div><div><p>За vamknam.by стоят два человека и любовь к именным подаркам. Мы создаём из дерева вещи, которые хочется дарить и оставлять на память.</p><p>В нашей мастерской есть место и маленькой копилке с именем, и подарку от целого класса. Ведь за каждым заказом — чья-то история.</p><span class="signature">С теплом, Ольга и Геннадий</span></div></div></section><div class="container"><section class="reviews" id="reviews"><div><div class="eyebrow">Истории наших подарков</div><h2>Самое ценное — ваши эмоции</h2><p>Отзывы покупателей и ещё больше работ — в нашем Instagram.</p></div><a class="button secondary" href="https://www.instagram.com/stories/highlights/18341259298247623/" target="_blank" rel="noopener">Смотреть отзывы <span>↗</span></a></section></div>`}
function catalog(){const cats=['Все изделия','Копилки','Мини-бары','Декор','Канцелярия'];if(!cats.includes(activeCategory))activeCategory='Все изделия';app.innerHTML=`<div class="container catalog-page">${breadcrumb('Каталог')}<div class="page-heading"><div class="eyebrow">Сделано с душой</div><h1>Каталог тёплых вещей</h1><p>Выберите подарок, а мы поможем сделать его личным. Имя, важная дата, ваши слова — всё начинается с идеи.</p></div><div class="catalog-toolbar"><div class="filters" aria-label="Категории">${cats.map(c=>`<button class="filter ${c===activeCategory?'active':''}" data-category="${c}" aria-pressed="${c===activeCategory}">${c}</button>`).join('')}</div><label><span class="sr-only">Сортировка </span><select id="sort" aria-label="Сортировка каталога"><option value="default">По умолчанию</option value="asc">Сначала дешевле</option><option value="desc">Сначала дороже</option></select></label></div><div class="products" id="catalog-products"></div><p id="catalog-count" class="count-caption"></p><p class="visual-note">Цены взяты из публикаций @vamknam.by и уточняются перед изготовлением. На первых четырёх карточках — студийные визуализации; оригиналы доступны на страницах изделий.</p></div>`;renderCatalog()}
function renderCatalog(){let ps=products.filter(p=>activeCategory==='Все изделия'||p.category===activeCategory);const sort=document.getElementById('sort').value;if(sort!=='default')ps.sort((a,b)=>sort==='asc'?a.price-b.price:b.price-a.price);document.getElementById('catalog-products').innerHTML=ps.map(card).join('');document.getElementById('catalog-count').textContent=`Изделий в подборке: ${ps.length}`;document.querySelectorAll('[data-category]').forEach(el=>{const on=el.dataset.category===activeCategory;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on)})}
function product(id){const p=products.find(x=>x.id===id);if(!p)return notFound();document.title=`${p.name} — vamknam.by`;app.innerHTML=`<div class="container">${breadcrumb(p.name,'<a href="catalog/">Каталог</a> &nbsp; / &nbsp; ')}<div class="product-layout"><div><img class="product-main" id="product-image" src="assets/${p.image}" alt="${p.name}" width="800" height="700"><div class="thumbnails"><button class="thumb active" data-photo="${p.image}" data-caption="${p.originalOnly?'Оригинальная фотография из Instagram.':'Студийная визуализация изделия.'}" aria-label="${p.originalOnly?'Основное фото':'Студийная визуализация'}"><img src="assets/${p.image}" alt="Основной вид"></button>${!p.originalOnly?`<button class="thumb" data-photo="${p.original}" data-caption="Оригинальная фотография из Instagram мастерской." aria-label="Оригинальная фотография"><img src="assets/${p.original}" alt="Оригинальная работа"></button>`:''}</div><p class="photo-caption" id="photo-caption">${p.originalOnly?'Оригинальная фотография из Instagram.':'Студийная визуализация изделия. Сравните с оригиналом во второй фотографии.'}</p></div><div class="product-info"><div class="eyebrow">${p.category} · На заказ</div><h1>${p.name}</h1><div class="large-price" id="product-price">${priceText(p)}</div><p class="product-description">${p.desc}</p><dl class="specs"><div><dt>Материал</dt><dd>${p.material}</dd></div><div><dt>Размер</dt><dd>${p.size}</dd></div><div><dt>Персонализация</dt><dd>По согласованию с мастером</dd></div><div><dt>Срок изготовления</dt><dd>Уточним перед заказом</dd></div></dl><form id="product-form" data-id="${p.id}"><label class="field">Ваша надпись или пожелания<input name="personalization" maxlength="140" placeholder="Например: имя, дата, тёплые слова"></label><div class="options">${p.id==='savings'?'<label class="field">Размер<select name="variant"><option value="small">12 × 12 см — 15 BYN</option><option value="large">15 × 15 см — 20 BYN</option></select></label>':''}<label class="field">Количество<input type="number" name="quantity" value="1" min="1" max="99" required></label></div><button class="button" type="submit">Добавить в корзину ${icon('bag')}</button></form><p class="small-note">${p.note}</p><a class="text-link" href="${p.source}" target="_blank" rel="noopener">Оригинальная публикация в Instagram <span>↗</span></a></div></div><section class="section" style="border-top:1px solid var(--line)"><div class="section-head"><h2>Ещё немного тепла</h2><a class="text-link" href="catalog/">В каталог ↗</a></div><div class="products">${products.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section></div>`}
function cartPage(){if(!cart.length){app.innerHTML=`<div class="container">${breadcrumb('Корзина')}<div class="empty"><div class="eyebrow">Всё начинается с маленького выбора</div><h2>Ваш подарок ещё впереди</h2><p>В корзине пока нет изделий. Давайте найдём что-то особенное.</p><a class="button" href="catalog/">Посмотреть каталог <span>↗</span></a></div></div>`;return}const total=cart.reduce((n,x)=>n+unitPrice(x)*x.qty,0);app.innerHTML=`<div class="container">${breadcrumb('Корзина')}<div class="page-heading"><div class="eyebrow">Почти ваш</div><h1>Выбранные подарки</h1></div><div class="cart-layout"><div>${cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<article class="cart-row"><img src="assets/${p.image}" alt="${p.name}"><div><h3><a href="product/${p.id}/">${p.name}</a></h3><p>${p.id==='savings'?(x.variant==='large'?'15 × 15 см':'12 × 12 см')+' · ':''}${escapeHTML(x.text)||'Без надписи'}</p><div class="qty"><button data-qty="${i}" data-delta="-1" aria-label="Уменьшить количество ${p.name}">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Увеличить количество ${p.name}">+</button></div></div><div><span class="price">${money(unitPrice(x)*x.qty)} BYN</span><br><button class="remove" data-remove="${i}" aria-label="Удалить ${p.name}">Убрать</button></div></article>`}).join('')}</div><aside class="cart-aside"><h2>Ваш тёплый подарок</h2><div class="total-row"><span>Предварительно</span><strong>${money(total)} BYN</strong></div><p>Доставка и персонализация согласовываются отдельно. Мастер подтвердит стоимость и сроки в переписке.</p><a class="button" href="how-to-order/?checkout=1">Подготовить заявку <span>↗</span></a><p class="small-note">Оплата на сайте не требуется. Заявку можно скопировать и отправить в Instagram мастерской.</p><a class="text-link" href="catalog/">Продолжить выбирать ↗</a></aside></div></div>`}
function orderPage(){app.innerHTML=`<div class="container">${breadcrumb('Как заказать')}<div class="page-heading"><div class="eyebrow">Просто и по-человечески</div><h1>Давайте создадим ваш подарок</h1><p>Выберите изделие или поделитесь идеей. Все детали обсудим лично в Instagram — от надписи до доставки.</p></div><div class="order-grid"><div class="order-content"><h2>01. Расскажите о подарке</h2><p>Название изделия, количество, имя или надпись и желаемая дата готовности. Можете собрать корзину или просто описать идею.</p><h2>02. Согласуем детали</h2><p>Мастер подтвердит оформление, окончательную стоимость, доступную дату и способ оплаты. Заявка на сайте помогает подготовить сообщение.</p><h2>03. Доставим по Беларуси</h2><p>В аккаунте мастерской указана отправка Белпочтой и Европочтой. Стоимость, сроки пересылки и возможность самовывоза уточняются при заказе.</p><details><summary>Можно добавить имя или свою надпись?</summary><p>Да, для многих изделий мастерская предлагает персонализацию. Укажите текст в заявке, а макет и возможность нанесения обсудите с мастером.</p></details><details><summary>Есть условия для группы или класса?</summary><p>Для копилок и именных ручек в публикациях есть цены от 5 штук. В корзине они рассчитываются автоматически. Итоговые условия подтвердит мастер.</p></details><details><summary>Когда будет готов заказ?</summary><p>Срок зависит от изделия, количества и загрузки мастерской. Напишите желаемую дату — Ольга и Геннадий уточнят возможность изготовления.</p></details></div><form class="order-form" id="order-form"><h2>${location.search.includes('custom')?'Ваша идея — наше вдохновение':'Подготовим вашу заявку'}</h2><label class="field">Как вас зовут<input name="name" placeholder="Ваше имя" maxlength="80" required autocomplete="given-name"></label><label class="field">Изделие, надпись или идея<textarea name="idea" placeholder="Что хочется подарить? Какую надпись добавить?" maxlength="2000" ${cart.length?'':'required'}></textarea></label><label class="field">Желаемая дата готовности<input type="date" name="date" min="${new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Minsk'})}"></label><label class="field">Способ получения<select name="delivery"><option>Обсудить с мастером</option><option>Европочта</option><option>Белпочта</option><option>Уточнить самовывоз</option></select></label><button class="button" type="submit">Составить сообщение <span>↗</span></button><p class="small-note">Данные остаются в вашем браузере. На следующем шаге вы сможете скопировать текст и самостоятельно отправить его в Instagram.</p><div id="order-result"></div></form></div></div>`}
function notFound(){app.innerHTML=`<div class="container not-found"><div class="eyebrow">Кажется, вы немного заблудились</div><h1>Такой страницы нет</h1><a class="button" href="catalog/">Вернуться в каталог ↗</a></div>`}
const basePath=new URL(document.baseURI).pathname;const path=('/'+location.pathname.slice(basePath.length)).replace(/\/+$/,'')||'/';if(path==='/')home();else if(path==='/catalog')catalog();else if(path.startsWith('/product/'))product(path.split('/')[2]);else if(path==='/cart')cartPage();else if(path==='/how-to-order')orderPage();else notFound();saveCart();
document.getElementById('menu-toggle').addEventListener('click',e=>{const b=e.currentTarget;const on=document.querySelector('.header nav').classList.toggle('open');b.setAttribute('aria-expanded',on);b.setAttribute('aria-label',on?'Закрыть меню':'Открыть меню')});
document.querySelector('.header nav').addEventListener('click',()=>{document.querySelector('.header nav').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add)addCart(add.dataset.add);const cat=e.target.closest('[data-category]');if(cat){activeCategory=cat.dataset.category;const url=new URL(location.href);url.searchParams.set('category',activeCategory);history.replaceState(null,'',url);renderCatalog()}const photo=e.target.closest('[data-photo]');if(photo){document.getElementById('product-image').src='assets/'+photo.dataset.photo;document.getElementById('photo-caption').textContent=photo.dataset.caption;document.querySelectorAll('.thumb').forEach(x=>x.classList.toggle('active',x===photo))}const q=e.target.closest('[data-qty]');if(q){const x=cart[Number(q.dataset.qty)];x.qty=Math.max(1,Math.min(99,x.qty+Number(q.dataset.delta)));saveCart();cartPage()}const remove=e.target.closest('[data-remove]');if(remove){cart.splice(Number(remove.dataset.remove),1);saveCart();cartPage()}if(e.target.closest('#copy-order'))copyOrder()});
document.addEventListener('change',e=>{if(e.target.id==='sort')renderCatalog();if(e.target.closest('#product-form')&&['variant','quantity'].includes(e.target.name)){const f=e.target.closest('form'),d=new FormData(f);const item={id:f.dataset.id,variant:d.get('variant')||'small',qty:Math.max(1,Number(d.get('quantity'))||1)};document.getElementById('product-price').innerHTML=`${unitPrice(item)} <small>BYN / шт.</small>`}});
let orderSummary='';document.addEventListener('submit',e=>{if(e.target.id==='product-form'){e.preventDefault();const d=new FormData(e.target);addCart(e.target.dataset.id,String(d.get('personalization')||'').trim(),String(d.get('variant')||'small'),Math.max(1,Math.min(99,Number(d.get('quantity'))||1)))}if(e.target.id==='order-form'){e.preventDefault();const d=new FormData(e.target);const lines=cart.map(x=>{const p=products.find(p=>p.id===x.id);return `• ${p.name}${p.id==='savings'?(x.variant==='large'?' (15 × 15 см)':' (12 × 12 см)'):''} — ${x.qty} шт., ${money(unitPrice(x)*x.qty)} BYN${x.text?'\n  Надпись: '+x.text:''}`});orderSummary=`Здравствуйте! Меня зовут ${d.get('name')}. Хочу обсудить заказ.\n\n${lines.length?lines.join('\n')+'\n\n':''}${d.get('idea')?'Идея и пожелания: '+d.get('idea')+'\n':''}${d.get('date')?'Желаемая дата: '+d.get('date')+'\n':''}Получение: ${d.get('delivery')}.${cart.length?'\nПредварительная стоимость изделий: '+money(cart.reduce((n,x)=>n+unitPrice(x)*x.qty,0))+' BYN.':''}\n\nПодскажите, пожалуйста, итоговую стоимость, комплектацию и срок изготовления.`;document.getElementById('order-result').innerHTML=`<h3 style="margin-top:28px">Сообщение готово</h3><p class="small-note">Скопируйте его, откройте Instagram и отправьте в Direct @vamknam.by. Заявка пока не отправлена.</p><pre class="summary-box">${escapeHTML(orderSummary)}</pre><div class="order-actions"><button type="button" id="copy-order" class="button secondary">Скопировать сообщение</button><a class="button" href="${IG}" target="_blank" rel="noopener">Открыть Instagram ↗</a></div>`;document.getElementById('order-result').scrollIntoView({behavior:'smooth',block:'center'})}});
async function copyOrder(){try{await navigator.clipboard.writeText(orderSummary);toast('Сообщение скопировано — отправьте его в Instagram');document.getElementById('copy-order').textContent='Скопировано ✓'}catch{toast('Выделите и скопируйте текст сообщения вручную')}}

document.addEventListener("input",e=>{if(e.target.closest("#product-form")&&e.target.name==="quantity")e.target.dispatchEvent(new Event("change",{bubbles:true}))});
